-- Phase 6: Schweizer PLZ-Verzeichnis mit Ort, Kanton, Mittelpunkt und Höhe über Meer.
-- Quelle: das Verzeichnis, das in V233 eingebaut war (offene Daten der Post und von swisstopo, Stand 2026).
-- Damit findet das CRM ohne Internet-Dienst den Ort zur PLZ, die ungefähre Lage für Karte und Route,
-- den Standort (Muri/Bulle) und die Höhe fürs Terminblatt. Keine Kundendaten.

create table public.plz_verzeichnis (
  plz     text primary key check (plz ~ '^[0-9]{4}$'),
  ort     text not null,
  kanton  text not null,
  breite  double precision not null,
  laenge  double precision not null,
  hoehe   int,
  -- Ortsname ohne Zusatz («Lausanne 26» → «lausanne»), für die Suche nach Ort.
  ort_name text generated always as (lower(regexp_replace(ort, '\s+\d+$', ''))) stored
);
comment on table public.plz_verzeichnis is 'Nachschlagetabelle, nur lesen; ändert sich nur über Migrationen.';
alter table public.plz_verzeichnis enable row level security;
create policy plz_lesen on public.plz_verzeichnis for select to authenticated using (true);
grant select on public.plz_verzeichnis to authenticated;
create index plz_verzeichnis_ort_idx on public.plz_verzeichnis (ort_name text_pattern_ops);

