-- Weitere Ortschaften mit derselben PLZ (z. B. 1723 Marly neben Pierrafortscha), damit die Suche nach
-- dem Ort auch kleine Orte findet. Quelle: Paket «swiss-zipcodes» 1.0.9 (MIT-Lizenz), nur Namen.
create table public.plz_ortschaften (
  plz      text not null references public.plz_verzeichnis (plz),
  ort      text not null,
  ort_name text generated always as (lower(ort)) stored,
  primary key (plz, ort)
);
alter table public.plz_ortschaften enable row level security;
create policy plz_lesen on public.plz_ortschaften for select to authenticated using (true);
grant select on public.plz_ortschaften to authenticated;
create index plz_ortschaften_ort_idx on public.plz_ortschaften (ort_name text_pattern_ops);

